<script setup>
import {computed} from 'vue';
import {Head,useForm,router} from '@inertiajs/vue3';
import AdminLayout from '../../Components/AdminLayout.vue';
const props=defineProps({users:Array,roles:Array,segments:Array,branches:Array,permissions:Array});
const form=useForm({user_id:'',role_id:'',segment_id:'',branch_id:''});
const global=computed(()=>['admin','super-admin'].includes(props.roles.find(r=>r.id===form.role_id)?.name));
const branches=computed(()=>props.branches.filter(b=>!form.segment_id||b.segments?.some(s=>s.id===form.segment_id)));
const roleForm=useForm({name:'',permissions:[]});
const internal=['super-admin','admin','manager','stock-manager','sales-manager','employee','content-manager'];
const editRole=useForm({id:'',permissions:[]});
function selectRole(){editRole.permissions=props.roles.find(r=>r.id===editRole.id)?.permissions.map(p=>p.name)||[];}
function grant(){form.transform(d=>({...d,segment_id:global.value?null:d.segment_id||null,branch_id:global.value?null:d.branch_id||null})).post('/admin/acessos');}
function revoke(user,data){if(confirm('Revogar este acesso e os tokens desta conta?'))router.delete('/admin/acessos/'+user.id,{data});}
</script>
<template><AdminLayout><Head title="Perfis e acessos"/><div class="page-heading"><div><span class="eyebrow">Sistema</span><h1>Perfis e acessos</h1><p>Cada concessão define o perfil, segmento e filial autorizados.</p></div></div><form class="panel admin-form" @submit.prevent="grant"><h2>Atribuir acesso</h2><div class="form-grid"><div class="field"><label for="access-user">Utilizador</label><select id="access-user" v-model="form.user_id" required><option value="">Selecionar…</option><option v-for="u in users" :key="u.id" :value="u.id">{{u.name}} · {{u.email}}</option></select></div><div class="field"><label for="access-role">Perfil</label><select id="access-role" v-model="form.role_id" required><option value="">Selecionar…</option><option v-for="r in roles" :key="r.id" :value="r.id">{{r.name}}</option></select></div><template v-if="!global"><div class="field"><label for="access-segment">Segmento</label><select id="access-segment" v-model="form.segment_id" required @change="form.branch_id=''" ><option value="">Selecionar…</option><option v-for="s in segments" :key="s.id" :value="s.id">{{s.name}}</option></select></div><div class="field"><label for="access-branch">Filial</label><select id="access-branch" v-model="form.branch_id"><option value="">Todas as filiais do segmento</option><option v-for="b in branches" :key="b.id" :value="b.id">{{b.name}}</option></select></div></template></div><button class="button" :disabled="form.processing">Atribuir acesso</button></form><section class="panel admin-form"><h2>Acessos atuais</h2><div v-for="u in users" :key="u.id" class="access-card"><h3>{{u.name}} <small class="muted">{{u.email}}</small></h3><div class="actions" v-for="r in u.roles" :key="'r'+r.id"><span class="badge">{{r.name}} · Global</span><button @click="revoke(u,{role_id:r.id})">Revogar</button></div><div class="actions" v-for="g in u.user_accesses" :key="g.id"><span class="badge">{{g.role?.name}} · {{g.segment?.name}} · {{g.branch?.name||'Todas as filiais'}}</span><button @click="revoke(u,{access_id:g.id})">Revogar</button></div><p v-if="!u.roles.length&&!u.user_accesses.length" class="muted">Sem concessões.</p></div></section><form v-if="permissions" class="panel admin-form" @submit.prevent="roleForm.post('/admin/perfis')"><h2>Criar perfil personalizado</h2><div class="field"><label for="role-name">Nome do perfil</label><input id="role-name" v-model="roleForm.name" required pattern="[a-z][a-z0-9-]+" placeholder="Ex.: assistente-catalogo"></div><div class="permission-grid"><label v-for="p in permissions" :key="p" class="checkbox-row"><input type="checkbox" v-model="roleForm.permissions" :value="p">{{p}}</label></div><button class="button" :disabled="roleForm.processing">Criar perfil</button></form><form v-if="roles.some(r=>!internal.includes(r.name))" class="panel admin-form" @submit.prevent="editRole.patch('/admin/perfis/'+editRole.id)"><h2>Editar perfil personalizado</h2><div class="field"><label for="edit-role">Perfil</label><select id="edit-role" v-model="editRole.id" required @change="selectRole"><option value="">Selecionar…</option><option v-for="r in roles.filter(r=>!internal.includes(r.name))" :key="r.id" :value="r.id">{{r.name}}</option></select></div><div v-if="editRole.id" class="permission-grid"><label v-for="p in permissions" :key="p" class="checkbox-row"><input type="checkbox" v-model="editRole.permissions" :value="p">{{p}}</label></div><button class="button" :disabled="editRole.processing||!editRole.id">Guardar permissões</button></form></AdminLayout></template>
